96-4672-8bf6-f21968d0fed5","extensionElements":{"nodeVisualInfo":[{"width":95,"x":-146,"y":179,"declaredType":"TNodeVisualInfo","height":70}]},"name":"set request header script","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.83b139d0-c3dd-4e0d-802c-bfe0ece0773e","scriptFormat":"text/x-javascript","script":{"content":["tw.local.odcRequest.BasicDetails.requestNature = tw.local.odcRequest.requestNature.name;
tw.local.odcRequest.BasicDetails.requestType = tw.local.odcRequest.requestType.name;
tw.local.odcRequest.initiator = tw.system.user.name;
tw.local.odcRequest.instanceNo = tw.system.processInstance.id;

if(tw.local.isFirstTime == true)
{
	tw.local.odcRequest.appInfo.status ="Initiated";
	tw.local.odcRequest.appInfo.subStatus ="Initiated";
	tw.local.odcRequest.appInfo.stepName =tw.epv.ScreenNames.RACT01;
	tw.local.odcRequest.appInfo.instanceID =tw.local.odcRequest.requestNo;
	
	tw.local.odcRequest.BasicDetails.requestState = "Undergoing Reversal";
	
//	tw.local.odcRequest.appInfo.requestName = "ODC Reversal";
	tw.local.odcRequest.appInfo.requestName = tw.epv.ProcessNames.odcReversal;

tw.local.actionConditions = {};
tw.local.actionConditions.complianceApproval= false;
tw.local.actionConditions.screenName= tw.epv.ScreenNames.RACT01;	
	
tw.local.odcRequest.stepLog ={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step = tw.epv.ScreenNames.RACT01;

if(!tw.local.odcRequest.ReversalReason) 
 tw.local.odcRequest.ReversalReason = {};

tw.local.odcRequest.History = [];

}
else
{

	tw.local.odcRequest.stepLog ={};
